'use strict';

/**
 * Build a greeting for the given name.
 * @param {string} name - Name to greet. An empty string is allowed.
 * @returns {string} The greeting in the form "Hello, <name>!".
 */
function greet(name) {
  return `Hello, ${name}!`;
}

// Named CJS export: Node's cjs-module-lexer detects this pattern, so
// `import { greet } from '../src/greet.js'` works in ESM files without
// a package.json (there is none in this project root).
module.exports.greet = greet;
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { greet } from '../src/greet.js';

test('greet builds a greeting for a regular name', () => {
  assert.equal(greet('Alice'), 'Hello, Alice!');
});

test('greet allows an empty name', () => {
  assert.equal(greet(''), 'Hello, !');
});

